        let p_view_masks_sz = dec.read_array_size_unchecked()?;
        let mut p_view_masks = Vec::with_capacity(p_view_masks_sz as usize);
        for _ in 0..p_view_masks_sz { p_view_masks.push(dec.read_u32()?); }
        let dependency_count = dec.read_u32()?;
        let p_view_offsets_sz = dec.read_array_size_unchecked()?;
        let mut p_view_offsets = Vec::with_capacity(p_view_offsets_sz as usize);
        for _ in 0..p_view_offsets_sz { p_view_offsets.push(dec.read_i32()?); }
        let correlation_mask_count = dec.read_u32()?;
        let p_correlation_masks_sz = dec.read_array_size_unchecked()?;
