        enc.write_u32(self.subpass_count)?;
        enc.write_array_size(self.p_view_masks.len() as u64)?;
        for item in &self.p_view_masks { enc.write_u32(*item)? }
        enc.write_u32(self.dependency_count)?;
        enc.write_array_size(self.p_view_offsets.len() as u64)?;
        for item in &self.p_view_offsets { enc.write_i32(*item)? }
        enc.write_u32(self.correlation_mask_count)?;
        enc.write_array_size(self.p_correlation_masks.len() as u64)?;
        for item in &self.p_correlation_masks { enc.write_u32(*item)? }
        Ok(())
