#[derive(Clone, Debug, Default, PartialEq)]
pub struct VkPipelineRenderingCreateInfo {
    pub s_type: VkStructureType,
    pub view_mask: u32,
    pub color_attachment_count: u32,
    pub p_color_attachment_formats: Vec<VkFormat>,
    pub depth_attachment_format: VkFormat,
    pub stencil_attachment_format: VkFormat,
}

impl VkPipelineRenderingCreateInfo {
    pub fn decode_self(dec: &mut Decoder<'_>, s_type: VkStructureType, _p_next: ()) -> Result<Self, WireError> {
        let view_mask = dec.read_u32()?;
        let color_attachment_count = dec.read_u32()?;
        let p_color_attachment_formats_sz = dec.read_array_size_unchecked()?;
        let mut p_color_attachment_formats = Vec::with_capacity(p_color_attachment_formats_sz as usize);
        for _ in 0..p_color_attachment_formats_sz { p_color_attachment_formats.push(VkFormat::decode(dec)?); }
        let depth_attachment_format = VkFormat::decode(dec)?;
        let stencil_attachment_format = VkFormat::decode(dec)?;
        Ok(Self {
            s_type,
            view_mask,
            color_attachment_count,
            p_color_attachment_formats,
            depth_attachment_format,
            stencil_attachment_format,
        })
    }

    pub fn decode(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let s_type = VkStructureType::decode(dec)?;
        if dec.read_simple_pointer()? { return Err(WireError::InvalidPointerFlag(1)); }
        Self::decode_self(dec, s_type, ())
    }

    pub fn decode_partial_self(dec: &mut Decoder<'_>, s_type: VkStructureType, _p_next: ()) -> Result<Self, WireError> {
        let _ = dec.read_array_size_unchecked()?;
        let mut out = Self::default();
        out.s_type = s_type;
        Ok(out)
    }

    pub fn decode_partial(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let s_type = VkStructureType::decode(dec)?;
        if dec.read_simple_pointer()? { return Err(WireError::InvalidPointerFlag(1)); }
        Self::decode_partial_self(dec, s_type, ())
    }

    pub fn encode_self<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        enc.write_u32(self.view_mask)?;
        enc.write_u32(self.color_attachment_count)?;
        enc.write_array_size(self.p_color_attachment_formats.len() as u64)?;
        for item in &self.p_color_attachment_formats { (*item).encode(enc)? }
        (self.depth_attachment_format).encode(enc)?;
        (self.stencil_attachment_format).encode(enc)?;
        Ok(())
    }

    pub fn encode<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        self.s_type.encode(enc)?;
        enc.write_simple_pointer(false)?;
        self.encode_self(enc)
    }

    pub fn encode_partial_self<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        enc.write_array_size(self.p_color_attachment_formats.len() as u64)?;
        Ok(())
    }

    pub fn encode_partial<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        self.s_type.encode(enc)?;
        enc.write_simple_pointer(false)?;
        self.encode_partial_self(enc)
    }
}

