#[derive(Clone, Debug, Default, PartialEq)]
pub struct VkApplicationInfo {
    pub s_type: VkStructureType,
    pub p_application_name: Option<String>,
    pub application_version: u32,
    pub p_engine_name: Option<String>,
    pub engine_version: u32,
    pub api_version: u32,
}

impl VkApplicationInfo {
    pub fn decode_self(dec: &mut Decoder<'_>, s_type: VkStructureType, _p_next: ()) -> Result<Self, WireError> {
        let p_application_name_sz = dec.read_array_size_unchecked()?;
        let p_application_name = if p_application_name_sz == 0 { None } else { Some(dec.read_string(p_application_name_sz as usize)?) };
        let application_version = dec.read_u32()?;
        let p_engine_name_sz = dec.read_array_size_unchecked()?;
        let p_engine_name = if p_engine_name_sz == 0 { None } else { Some(dec.read_string(p_engine_name_sz as usize)?) };
        let engine_version = dec.read_u32()?;
        let api_version = dec.read_u32()?;
        Ok(Self {
            s_type,
            p_application_name,
            application_version,
            p_engine_name,
            engine_version,
            api_version,
        })
    }

    pub fn decode(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let s_type = VkStructureType::decode(dec)?;
        if dec.read_simple_pointer()? { return Err(WireError::InvalidPointerFlag(1)); }
        Self::decode_self(dec, s_type, ())
    }

    pub fn decode_partial_self(dec: &mut Decoder<'_>, s_type: VkStructureType, _p_next: ()) -> Result<Self, WireError> {
        let _ = dec.read_array_size_unchecked()?;
        let _ = dec.read_array_size_unchecked()?;
        let mut out = Self::default();
        out.s_type = s_type;
        Ok(out)
    }

    pub fn decode_partial(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let s_type = VkStructureType::decode(dec)?;
        if dec.read_simple_pointer()? { return Err(WireError::InvalidPointerFlag(1)); }
        Self::decode_partial_self(dec, s_type, ())
    }

    pub fn encode_self<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        match &self.p_application_name {
            None => enc.write_array_size(0)?,
            Some(s) => {
                let bytes = s.as_bytes();
                enc.write_array_size((bytes.len() + 1) as u64)?;
                let mut buf = Vec::with_capacity(bytes.len() + 1);
                buf.extend_from_slice(bytes);
                buf.push(0);
                enc.write_cstr_bytes(&buf)?;
            }
        }
        enc.write_u32(self.application_version)?;
        match &self.p_engine_name {
            None => enc.write_array_size(0)?,
            Some(s) => {
                let bytes = s.as_bytes();
                enc.write_array_size((bytes.len() + 1) as u64)?;
                let mut buf = Vec::with_capacity(bytes.len() + 1);
                buf.extend_from_slice(bytes);
                buf.push(0);
                enc.write_cstr_bytes(&buf)?;
            }
        }
        enc.write_u32(self.engine_version)?;
        enc.write_u32(self.api_version)?;
        Ok(())
    }

    pub fn encode<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        self.s_type.encode(enc)?;
        enc.write_simple_pointer(false)?;
        self.encode_self(enc)
    }

    pub fn encode_partial_self<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        enc.write_array_size(self.p_application_name.as_ref().map_or(0, |s| s.len() + 1) as u64)?;
        enc.write_array_size(self.p_engine_name.as_ref().map_or(0, |s| s.len() + 1) as u64)?;
        Ok(())
    }

    pub fn encode_partial<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        self.s_type.encode(enc)?;
        enc.write_simple_pointer(false)?;
        self.encode_partial_self(enc)
    }
}

