#[derive(Clone, Debug, PartialEq)]
pub struct VkPhysicalDeviceMemoryProperties {
    pub memory_type_count: u32,
    pub memory_types: [VkMemoryType; VK_MAX_MEMORY_TYPES],
    pub memory_heap_count: u32,
    pub memory_heaps: [VkMemoryHeap; VK_MAX_MEMORY_HEAPS],
}

impl Default for VkPhysicalDeviceMemoryProperties {
    fn default() -> Self {
        Self {
            memory_type_count: Default::default(),
            memory_types: core::array::from_fn(|_| Default::default()),
            memory_heap_count: Default::default(),
            memory_heaps: core::array::from_fn(|_| Default::default()),
        }
    }
}

impl VkPhysicalDeviceMemoryProperties {
    pub fn decode(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let memory_type_count = dec.read_u32()?;
        dec.read_array_size(VK_MAX_MEMORY_TYPES as u64)?;
        let mut memory_types = core::array::from_fn(|_| Default::default());
        for item in &mut memory_types { *item = VkMemoryType::decode(dec)?; }
        let memory_heap_count = dec.read_u32()?;
        dec.read_array_size(VK_MAX_MEMORY_HEAPS as u64)?;
        let mut memory_heaps = core::array::from_fn(|_| Default::default());
        for item in &mut memory_heaps { *item = VkMemoryHeap::decode(dec)?; }
        Ok(Self {
            memory_type_count,
            memory_types,
            memory_heap_count,
            memory_heaps,
        })
    }

    pub fn decode_partial(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let _sz = dec.read_array_size(VK_MAX_MEMORY_TYPES as u64)?;
        for _ in 0.._sz { let _ = VkMemoryType::decode_partial(dec)?; }
        let _sz = dec.read_array_size(VK_MAX_MEMORY_HEAPS as u64)?;
        for _ in 0.._sz { let _ = VkMemoryHeap::decode_partial(dec)?; }
        Ok(Self::default())
    }

    pub fn encode<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        enc.write_u32(self.memory_type_count)?;
        enc.write_array_size(VK_MAX_MEMORY_TYPES as u64)?;
        for item in &self.memory_types { (item).encode(enc)? }
        enc.write_u32(self.memory_heap_count)?;
        enc.write_array_size(VK_MAX_MEMORY_HEAPS as u64)?;
        for item in &self.memory_heaps { (item).encode(enc)? }
        Ok(())
    }

    pub fn encode_partial<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        enc.write_array_size(VK_MAX_MEMORY_TYPES as u64)?;
        for item in &self.memory_types { item.encode_partial(enc)?; }
        enc.write_array_size(VK_MAX_MEMORY_HEAPS as u64)?;
        for item in &self.memory_heaps { item.encode_partial(enc)?; }
        Ok(())
    }
}

