#[derive(Clone, Debug, Default, PartialEq)]
pub struct VkPipelineLayoutCreateInfo {
    pub s_type: VkStructureType,
    pub flags: VkPipelineLayoutCreateFlags,
    pub set_layout_count: u32,
    pub p_set_layouts: Vec<VkDescriptorSetLayout>,
    pub push_constant_range_count: u32,
    pub p_push_constant_ranges: Vec<VkPushConstantRange>,
}

impl VkPipelineLayoutCreateInfo {
    pub fn decode_self(dec: &mut Decoder<'_>, s_type: VkStructureType, _p_next: ()) -> Result<Self, WireError> {
        let flags = dec.read_u32()?;
        let set_layout_count = dec.read_u32()?;
        let p_set_layouts_sz = dec.read_array_size_unchecked()?;
        let mut p_set_layouts = Vec::with_capacity(p_set_layouts_sz as usize);
        for _ in 0..p_set_layouts_sz { p_set_layouts.push(VkDescriptorSetLayout::decode(dec)?); }
        let push_constant_range_count = dec.read_u32()?;
        let p_push_constant_ranges_sz = dec.read_array_size_unchecked()?;
        let mut p_push_constant_ranges = Vec::with_capacity(p_push_constant_ranges_sz as usize);
        for _ in 0..p_push_constant_ranges_sz { p_push_constant_ranges.push(VkPushConstantRange::decode(dec)?); }
        Ok(Self {
            s_type,
            flags,
            set_layout_count,
            p_set_layouts,
            push_constant_range_count,
            p_push_constant_ranges,
        })
    }

    pub fn decode(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let s_type = VkStructureType::decode(dec)?;
        if dec.read_simple_pointer()? { return Err(WireError::InvalidPointerFlag(1)); }
        Self::decode_self(dec, s_type, ())
    }

    pub fn decode_partial_self(dec: &mut Decoder<'_>, s_type: VkStructureType, _p_next: ()) -> Result<Self, WireError> {
        let _ = dec.read_array_size_unchecked()?;
        let _ = dec.read_array_size_unchecked()?;
        let mut out = Self::default();
        out.s_type = s_type;
        Ok(out)
    }

    pub fn decode_partial(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let s_type = VkStructureType::decode(dec)?;
        if dec.read_simple_pointer()? { return Err(WireError::InvalidPointerFlag(1)); }
        Self::decode_partial_self(dec, s_type, ())
    }

    pub fn encode_self<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        enc.write_u32(self.flags)?;
        enc.write_u32(self.set_layout_count)?;
        enc.write_array_size(self.p_set_layouts.len() as u64)?;
        for item in &self.p_set_layouts { (*item).encode(enc)? }
        enc.write_u32(self.push_constant_range_count)?;
        enc.write_array_size(self.p_push_constant_ranges.len() as u64)?;
        for item in &self.p_push_constant_ranges { (item).encode(enc)? }
        Ok(())
    }

    pub fn encode<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        self.s_type.encode(enc)?;
        enc.write_simple_pointer(false)?;
        self.encode_self(enc)
    }

    pub fn encode_partial_self<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        enc.write_array_size(self.p_set_layouts.len() as u64)?;
        enc.write_array_size(self.p_push_constant_ranges.len() as u64)?;
        Ok(())
    }

    pub fn encode_partial<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        self.s_type.encode(enc)?;
        enc.write_simple_pointer(false)?;
        self.encode_partial_self(enc)
    }
}

