#[derive(Clone, Debug, Default, PartialEq)]
pub struct VkSubpassDescription {
    pub flags: VkSubpassDescriptionFlags,
    pub pipeline_bind_point: VkPipelineBindPoint,
    pub input_attachment_count: u32,
    pub p_input_attachments: Vec<VkAttachmentReference>,
    pub color_attachment_count: u32,
    pub p_color_attachments: Vec<VkAttachmentReference>,
    pub p_resolve_attachments: Vec<VkAttachmentReference>,
    pub p_depth_stencil_attachment: Option<Box<VkAttachmentReference>>,
    pub preserve_attachment_count: u32,
    pub p_preserve_attachments: Vec<u32>,
}

impl VkSubpassDescription {
    pub fn decode(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let flags = dec.read_u32()?;
        let pipeline_bind_point = VkPipelineBindPoint::decode(dec)?;
        let input_attachment_count = dec.read_u32()?;
        let p_input_attachments_sz = dec.read_array_size_unchecked()?;
        let mut p_input_attachments = Vec::with_capacity(p_input_attachments_sz as usize);
        for _ in 0..p_input_attachments_sz { p_input_attachments.push(VkAttachmentReference::decode(dec)?); }
        let color_attachment_count = dec.read_u32()?;
        let p_color_attachments_sz = dec.read_array_size_unchecked()?;
        let mut p_color_attachments = Vec::with_capacity(p_color_attachments_sz as usize);
        for _ in 0..p_color_attachments_sz { p_color_attachments.push(VkAttachmentReference::decode(dec)?); }
        let p_resolve_attachments_sz = dec.read_array_size_unchecked()?;
        let mut p_resolve_attachments = Vec::with_capacity(p_resolve_attachments_sz as usize);
        for _ in 0..p_resolve_attachments_sz { p_resolve_attachments.push(VkAttachmentReference::decode(dec)?); }
        let p_depth_stencil_attachment = if dec.read_simple_pointer()? { Some(Box::new(VkAttachmentReference::decode(dec)?)) } else { None };
        let preserve_attachment_count = dec.read_u32()?;
        let p_preserve_attachments_sz = dec.read_array_size_unchecked()?;
        let mut p_preserve_attachments = Vec::with_capacity(p_preserve_attachments_sz as usize);
        for _ in 0..p_preserve_attachments_sz { p_preserve_attachments.push(dec.read_u32()?); }
        Ok(Self {
            flags,
            pipeline_bind_point,
            input_attachment_count,
            p_input_attachments,
            color_attachment_count,
            p_color_attachments,
            p_resolve_attachments,
            p_depth_stencil_attachment,
            preserve_attachment_count,
            p_preserve_attachments,
        })
    }

    pub fn decode_partial(dec: &mut Decoder<'_>) -> Result<Self, WireError> {
        let _ = dec.read_array_size_unchecked()?;
        let _ = dec.read_array_size_unchecked()?;
        let _ = dec.read_array_size_unchecked()?;
        let _ = dec.read_simple_pointer()?;
        let _ = dec.read_array_size_unchecked()?;
        Ok(Self::default())
    }

    pub fn encode<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        enc.write_u32(self.flags)?;
        (self.pipeline_bind_point).encode(enc)?;
        enc.write_u32(self.input_attachment_count)?;
        enc.write_array_size(self.p_input_attachments.len() as u64)?;
        for item in &self.p_input_attachments { (item).encode(enc)? }
        enc.write_u32(self.color_attachment_count)?;
        enc.write_array_size(self.p_color_attachments.len() as u64)?;
        for item in &self.p_color_attachments { (item).encode(enc)? }
        enc.write_array_size(self.p_resolve_attachments.len() as u64)?;
        for item in &self.p_resolve_attachments { (item).encode(enc)? }
        match &self.p_depth_stencil_attachment {
            None => enc.write_simple_pointer(false)?,
            Some(v) => { enc.write_simple_pointer(true)?; (v).encode(enc)?; }
        }
        enc.write_u32(self.preserve_attachment_count)?;
        enc.write_array_size(self.p_preserve_attachments.len() as u64)?;
        for item in &self.p_preserve_attachments { enc.write_u32(*item)? }
        Ok(())
    }

    pub fn encode_partial<S: WireSink>(&self, enc: &mut Encoder<S>) -> Result<(), WireError> {
        enc.write_array_size(self.p_input_attachments.len() as u64)?;
        enc.write_array_size(self.p_color_attachments.len() as u64)?;
        enc.write_array_size(self.p_resolve_attachments.len() as u64)?;
        enc.write_simple_pointer(self.p_depth_stencil_attachment.is_some())?;
        enc.write_array_size(self.p_preserve_attachments.len() as u64)?;
        Ok(())
    }
}

